import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

# We investigate the case where p=2, d3=q=3, and d5=r (r must be prime > 3)
# n = 2*3 + 2*r + 3*r = 6 + 5r
# We test small primes r = 5, 7, 11, 13, 17, 19
primes_to_test = [5, 7, 11, 13, 17, 19, 23]

results = {}
for r in primes_to_test:
    n = 6 + 5 * r

    # Check divisor constraints
    divisors = get_divisors(n)

    # d1=1, d2=2, d3=3, d4=?, d5=r

    if len(divisors) >= 5 and divisors[0] == 1 and divisors[1] == 2 and divisors[2] == 3:
        # Check if d5 is indeed r
        if divisors[4] == r:
            # Verification check (should always hold if derived correctly, but good practice)
            ab_ac_bc = 2*3 + 2*r + 3*r
            if ab_ac_bc == n:
                tau_n = len(divisors)
                results[n] = {"r": r, "tau": tau_n, "divisors": divisors}

print(results)
